{
  "contractVersion": "modeling-proposal-v1",
  "baselineVersion": null,
  "reuse": [],
  "newAttributes": [
    {
      "id": "handtowel.folded_sheet_size",
      "name": "折叠后单张尺寸",
      "conceptKey": "paper.folded_sheet_size",
      "definition": "抽式擦手纸单张纸在折叠状态下的宽×高尺寸，单位mm；按来源原文记录，如230×200mm。该尺寸用于判断补充装与分配器开口/容腔的适配及单张覆盖范围，不与展开尺寸、包装尺寸、分配器尺寸或物流尺寸混用。",
      "scope": "抽式擦手纸成品单张（折叠状态）",
      "fieldType": "text",
      "unit": null,
      "enumValues": [],
      "multi": false,
      "numberConfig": null,
      "textConfig": {
        "format": "ANY",
        "minLength": 1,
        "maxLength": 300,
        "displayMethod": null,
        "trim": true
      },
      "optionConfig": null,
      "rationale": "采购更换抽式擦手纸时，需要判断补充装能否装入既有分配器，并比较单张覆盖面积和手感；折叠后尺寸直接改变适配与比较判断，与基础字段的商品包装长宽高职责不同。当前按组合文本保留宽×高，避免在未确认长宽各自独立筛选/适配用途前强拆。",
      "references": [
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "擦手耗材与设备配套及纸张对象"
        },
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "分配器系统、卷式与折叠式差异、性能独立用途"
        },
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "不可因简化而混同净重/毛重、内径/外径、单张/整卷/包装。"
        }
      ]
    },
    {
      "id": "handtowel.material",
      "name": "原料",
      "conceptKey": "paper.material",
      "definition": "成品纸张所用纤维原料，按包装或厂家资料原文记录，如原生木浆、再生浆、混合浆；不把品牌或系列名称当作原料，不推断未标注成分，不做未经登记的同义归一。",
      "scope": "抽式擦手纸成品纸张",
      "fieldType": "text",
      "unit": null,
      "enumValues": [],
      "multi": false,
      "numberConfig": null,
      "textConfig": {
        "format": "ANY",
        "minLength": 1,
        "maxLength": 300,
        "displayMethod": null,
        "trim": true
      },
      "optionConfig": null,
      "rationale": "原料影响吸水、柔软度、掉屑和成本，是采购比较与替代选型的基本参数；保留原文可避免把纯木浆、原生木浆等未经核实的概念混同。",
      "references": [
        {
          "id": "small-roll-paper-research-20261022",
          "kind": "knowledge",
          "version": "df125eba0fa816879dbea0ab67a14c452384750360ca3993c28f54e34335f4f7",
          "quote": "原料保留商家确切措辞：纯木浆不自动等于原生木浆；品牌或系列宣传不证明该SKU材料。"
        },
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "名称用不歧义的短称，计量对象、分母、口径和限制写在定义。"
        }
      ]
    },
    {
      "id": "handtowel.package_contents",
      "name": "每包内数量",
      "conceptKey": "paper.package_contents",
      "definition": "按来源原文记录一个内包装（包）内的成品纸张数量及计数词，如200抽/包、200张/包；不统一抽与张，不乘层数，不把箱内包数记入本属性（箱规由销售单位与最小计量单位数量表达）。",
      "scope": "抽式擦手纸内包装（包）",
      "fieldType": "text",
      "unit": null,
      "enumValues": [],
      "multi": false,
      "numberConfig": null,
      "textConfig": {
        "format": "ANY",
        "minLength": 1,
        "maxLength": 300,
        "displayMethod": null,
        "trim": true
      },
      "optionConfig": null,
      "rationale": "采购需要比较每包可用量和单位使用成本；销售单位为箱时，箱规不能替代每包内数量，因此该参数有独立用途。因来源可能使用抽或张且换算关系未核实，先用单个文本保留原文数量、计数词和包分母。",
      "references": [
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "不统一张、抽、节、格，不按层数换算张数。"
        },
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "固定数值及单位合为一个定义；真正可变计数词先用保留原文的单个文本，不拆独立单位字段。"
        }
      ]
    }
  ],
  "newBindings": [
    {
      "attributeId": "handtowel.folded_sheet_size",
      "requiredness": "optional",
      "requirednessReason": "缺失会妨碍判断能否装入既有分配器及比较单张覆盖面积；但强制填写必要性尚未经业务确认，先选填。",
      "isKeySpec": false,
      "isPublic": true,
      "searchable": true,
      "displayInTitle": false,
      "displayInList": false,
      "sortIndex": 1,
      "uses": [
        "selection",
        "comparison",
        "search",
        "display"
      ],
      "differenceReason": null
    },
    {
      "attributeId": "handtowel.package_contents",
      "requiredness": "optional",
      "requirednessReason": "缺失会妨碍每包可用量和单位使用成本比较；销售单位为包时可由系统unitMinQua承担，是否强制填写待业务确认，先选填。",
      "isKeySpec": false,
      "isPublic": true,
      "searchable": true,
      "displayInTitle": false,
      "displayInList": false,
      "sortIndex": 2,
      "uses": [
        "selection",
