        "search",
        "display"
      ],
      "differenceReason": null
    },
    {
      "attributeId": "handtowel.material",
      "requiredness": "optional",
      "requirednessReason": "缺失会影响原料替代和成本比较；是否强制填写待业务确认，先选填。",
      "isKeySpec": false,
      "isPublic": true,
      "searchable": true,
      "displayInTitle": false,
      "displayInList": false,
      "sortIndex": 3,
      "uses": [
        "selection",
        "comparison",
        "search",
        "display"
      ],
      "differenceReason": null
    }
  ],
  "newExtensionCandidates": [
    {
      "id": "candidate.handtowel.layers",
      "name": "层数",
      "conceptKey": "paper.layers",
      "scope": "抽式擦手纸成品纸张叠层",
      "potentialUse": "比较单抽厚实度、吸水、掉屑和成本；层数是抽式擦手纸采购替换和规格比较的常见维度。",
      "deferReason": "属性池已有 roll.layers（定义：成品纸张叠层数量，不是包装或托盘层数），但其目标类目适用性未覆盖抽式擦手纸（reusable=false，缺目标类目核实记录）。不能以新ID复制同一口径绕过范围检查，故先保留扩展候选。",
      "references": [
        {
          "id": "small-roll-paper-research-20261022",
          "kind": "knowledge",
          "version": "df125eba0fa816879dbea0ab67a14c452384750360ca3993c28f54e34335f4f7",
          "quote": "层数是成品纸张叠层；不能与托盘层数、包装层级混淆。"
        },
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "擦手耗材与设备配套及纸张对象"
        }
      ],
      "activationRequirements": [
        {
          "kind": "target_applicability",
          "question": "核实属性池 roll.layers 的冻结定义是否适用于抽式擦手纸；若适用则复用，若不适用再评估独立定义。"
        },
        {
          "kind": "professional_definition",
          "question": "确认抽式擦手纸的层数是否采用成品纸张叠层口径，以及单抽是否可能由多层复合。"
        },
        {
          "kind": "business_use",
          "question": "确认层数是否作为采购选型或比较的必需要素，还是仅作展示信息。"
        }
      ]
    },
    {
      "id": "candidate.handtowel.embossing",
      "name": "压花",
      "conceptKey": "paper.embossing",
      "scope": "抽式擦手纸纸面压花工艺",
      "potentialUse": "压花影响层间结合、吸水、分离手感和外观，可作为采购比较与展示参数。",
      "deferReason": "本轮未确认压花的有无、图案或工艺表达口径，也未确认其与印花的关系；不能设互斥枚举或直接转为选填属性。",
      "references": [
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "印花与压花是不同概念，本轮在小卷族均为扩展候选，不误并为“印花工艺”。"
        }
      ],
      "activationRequirements": [
        {
          "kind": "business_use",
          "question": "确认压花是否作为抽式擦手纸的采购选型、比较或展示维度。"
        },
        {
          "kind": "professional_definition",
          "question": "明确压花的有无、图案或工艺的表达口径，以及其与印花能否同时成立。"
        },
        {
          "kind": "target_applicability",
          "question": "确认压花候选适用于抽式擦手纸，而非仅沿用卷纸或面巾纸场景。"
        }
      ]
    },
    {
      "id": "candidate.handtowel.printing",
      "name": "印花",
      "conceptKey": "paper.printing",
      "scope": "抽式擦手纸纸面印刷图案",
      "potentialUse": "图案或印刷影响外观和场景选择，可用于展示与比较。",
      "deferReason": "与小卷纸的印花候选概念相近但目标适用性未核实；印花与压花是不同概念，不能把压花当印花的下位值，也不能硬做互斥枚举。",
      "references": [
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "印花与压花是不同概念，本轮在小卷族均为扩展候选，不误并为“印花工艺”。"
        }
      ],
      "activationRequirements": [
        {
          "kind": "business_use",
          "question": "确认印花是否作为抽式擦手纸的采购选型、比较或展示维度。"
        },
        {
          "kind": "professional_definition",
          "question": "明确印花的有无、图案或印刷方式的表达口径，以及其与压花能否同时成立。"
        },
        {
          "kind": "target_applicability",
          "question": "确认印花候选适用于抽式擦手纸，而非仅沿用卷纸或面巾纸场景。"
        }
      ]
    },
    {
      "id": "candidate.handtowel.dispenser_compatibility",
      "name": "适配分配器",
      "conceptKey": "dispenser.compatibility",
      "scope": "抽式擦手纸补充装与分配器系统的适配关系",
      "potentialUse": "判断补充装能否装入既有擦手纸分配器，直接影响替换采购和补货。",
      "deferReason": "需要型号级兼容关系或明确的分配器系统口径；当前无可靠体系，不能由折叠后单张尺寸推断兼容性。",
      "references": [
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "器具适配关系与器具本体参数需要区分"
        },
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "擦手耗材与设备配套及纸张对象"
        }
      ],
      "activationRequirements": [
        {
          "kind": "business_use",
          "question": "确认是否以适配现有分配器系统或型号作为抽式擦手纸的采购筛选条件。"
        },
        {
          "kind": "professional_definition",
          "question": "定义兼容关系的表达口径：按分配器型号、系列还是接口尺寸，以及如何核实。"
        },
        {
          "kind": "target_applicability",
          "question": "明确适配关系覆盖的分配器系统或型号范围，不能由外形尺寸直接推断。"
        }
      ]
    },
    {
      "id": "candidate.handtowel.absorbency",
      "name": "吸水性能",
      "conceptKey": "paper.absorbency",
      "scope": "抽式擦手纸成品纸张的吸水性能",
      "potentialUse": "比较擦手效率和单次耗用量；采购可能据此选择不同档次产品。",
      "deferReason": "缺少可核对的测试方法、指标和标称口径，不能编造秒数、倍率或等级；业务是否以此比较尚未确认。",
      "references": [
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "分配器系统、卷式与折叠式差异、性能独立用途"
        },
        {
          "id": "clean-paper-admission-20261023",
          "kind": "knowledge",
          "version": "67d179e3644faf864e453e85c39fa69ba331f640cb134e711a6ab728a833a661",
          "quote": "未知性能直接枚举"
        }
      ],
      "activationRequirements": [
        {
          "kind": "business_use",
          "question": "确认吸水性能是否作为抽式擦手纸的采购比较项，还是仅作宣传信息。"
        },
        {
          "kind": "professional_definition",
          "question": "明确吸水性能的测试方法、指标、单位或等级，以及来源证据要求。"
        },
        {
          "kind": "target_applicability",
          "question": "确认该性能口径适用于抽式擦手纸，不直接沿用其他纸品或实验室方法。"
        }
      ]
    },
    {
      "id": "candidate.handtowel.wet_strength",
      "name": "湿强度",
      "conceptKey": "paper.wet_strength",
      "scope": "抽式擦手纸湿水后的抗破损性能",
      "potentialUse": "判断擦手时是否易破、是否掉屑，影响使用体验和单次耗用量。",
      "deferReason": "缺少可核对的测试方法和指标口径，不能编造数值或等级；业务是否以此比较尚未确认。",
